                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < H and 0 <= xx < W and (yy, xx) not in seen
                            and g[yy][xx] not in (0, 4)):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            ys = [p[0] for p in comp]
            xs = [p[1] for p in comp]
            y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
            if len(comp) != (y1 - y0 + 1) * (x1 - x0 + 1):
                continue
            color = g[y0][x0]
            marks = [(y, x, g[y][x]) for y, x in comp
                     if y0 < y < y1 and x0 < x < x1 and g[y][x] != color]
            heads = [(y, x) for y, x, v in marks if v == 2]
            tails = [(y, x) for y, x, v in marks if v != 2]
            if not heads or not tails:
                continue
            sign = 1 if any(v == 1 for _, _, v in marks) else -1
            dr = sign * (sum(y for y, x in heads) / len(heads)
                         - sum(y for y, x in tails) / len(tails))
            dc = sign * (sum(x for y, x in heads) / len(heads)
                         - sum(x for y, x in tails) / len(tails))
            keys[color] = ((dr > 0) - (dr < 0), (dc > 0) - (dc < 0))

    chambers = {}
    for r in range(H):
        for c in range(W):
            if g[r][c] != 4:
                continue
            stack = [(r, c)]
            visited = {(r, c)}
            walls = set()
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if not (0 <= yy < H and 0 <= xx < W):
